function getTileLayer() {
    return new ARPAVAPI.openlayers.layer.Tile({
        source: new ARPAVAPI.openlayers.source.OSM({
            url: 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Topo_Map/MapServer/tile/{z}/{y}/{x}',
