/**
 * cancello i layer delle stazioni
 */    
function cancellaLayer() {
    map.getLayers().forEach(layer => {
        if ( layer && layer.get('name') ) {
            if ( layer.get('name') == layerMappa) {
                map.removeLayer(layer);
            }
        }
    });
}


