/**
 * recupero le stazioni e le visualizzo
 */
async function addStazioni() {

    if (document.getElementById('aggiornamento')) {
        document.getElementById('aggiornamento').innerHTML = 'Recupero stazioni';
    }        

    const lnk = lnkStazioni + currentBtn.coordcd + '&rnd=' + Math.random();  
    const response = await fetch(lnk);
    const jsonResponse = (await response.json());
    const stzData = jsonResponse.data;

    // oggetto geoJSON
    const geojsonObject = {
                type: 'FeatureCollection',
                crs: {
                    type: 'name',
                    properties: {
                        name: 'EPSG:3857',
                    },
                },
                features: [],
            };

    // carico le stazioni nel geoJSON e valorizzo le variabili per le informazioni
    let dataAggio = 0, dataRifer = 0;

    let coord = [];

    stzData.forEach((stazione, index) => {  

        if ( ! eleStaz.includes(stazione.codice_stazione) ) {
            return;
        }

        let posiz = 'bottom';
        if ( coord.includes( stazione.point)  ) {
            posiz = 'top';
        }
        coord.push( stazione.point );

        geojsonObject.features.push({
            type: 'Feature',
            geometry: JSON.parse(stazione.point),
            properties: {
                id: stazione.codice_stazione,
                xTextBaseline: posiz,
                data: { ...stazione },              // tutte le proprietà della stazione presente nel json
            },
        });

    });


    var PallinoStazione = new ARPAVAPI.openlayers.style.Circle({
        radius: pointDimension,
        fill: new ARPAVAPI.openlayers.style.Fill({color: colorFill}),
        stroke: new ARPAVAPI.openlayers.style.Stroke({
          color: colorLine, 
          width: 1
        })
      });


    // punto della stazione di colore standard
    let iconStyle = new ARPAVAPI.openlayers.style.Style({
      image: PallinoStazione
    });

    // label stazione    
    var labelStyle = new ARPAVAPI.openlayers.style.Style({
        text: new ARPAVAPI.openlayers.style.Text({
            placement: 'point',
            font: fontStz,
            overflow: true,
            fill: new ARPAVAPI.openlayers.style.Fill({
                color: 'black',
            }),
            stroke: new ARPAVAPI.openlayers.style.Stroke({
                color: sfondoEtichetta,
                width: 4,
            }),
            offsetY: -3,
            textBaseline: 'bottom',
            textAlign: 'center', 
            rotation: 0,

        })
    });
    var style = [iconStyle, labelStyle];

