// ValoriSensore: ritorna i valori dei sensori ordinati
function ValoriSensore(stationdata) {
    let sensors = {};

    stationdata.data.forEach((item) => {
        if (!sensors[item.tipo]) {
            sensors[item.tipo] = {
                data: [],
                label: item.nome_sensore,
                unitmeas: item.unitnm
            }
        }

        // momento di aggiornamento dei dati visualizzati
        aggiornamento = item.aggiornamento;
        precisionefalda = item.precisionefalda;
        nomeStazione = item.nome_stazione;

        sensors[item.tipo].data.push({
            value: item.valore,
            date: item.dataora
        });
    });

    // ora separo, per i sensori con value: MINIMO, MEDIO o MASSIMO su sensori appositi
    Object.entries(sensors).forEach(([key, contenuto], index) => {
        console.log(`${index}: ${key} = ${contenuto.label}`);
        // sensori con più valori:  gestione delle colonne multiple per il sensore
        if (key.indexOf('TARIA') >= 0 ) {   
            sensors[ key + "_MIN" ] = { label: contenuto.label + ' (minima)', unitmeas: contenuto.unitmeas, data: []};
            sensors[ key + "_MED" ] = { label: contenuto.label + ' (media)', unitmeas: contenuto.unitmeas, data: []};
            sensors[ key + "_MAX" ] = { label: contenuto.label + ' (massima)', unitmeas: contenuto.unitmeas, data: []};
            contenuto.data.forEach(element => {
                let valore = {MINIMO: null, MEDIO: null, MASSIMO: null};
                if (element.value) {
                    valore = JSON.parse(element.value);
                }
                const giorno = new Date().ConvData( element.date );
                sensors[ key + "_MIN" ].data.push( { date: element.date, value: valore.MINIMO, timestamp: giorno } );
                sensors[ key + "_MED" ].data.push( { date: element.date, value: valore.MEDIO, timestamp: giorno } );
                sensors[ key + "_MAX" ].data.push( { date: element.date, value: valore.MASSIMO, timestamp: giorno } );
            });
        }
        if (key.indexOf('UMID') >= 0 ) {   
            sensors[ key + "_MIN" ] = { label: contenuto.label + ' (minima)', unitmeas: contenuto.unitmeas, data: []};
            sensors[ key + "_MAX" ] = { label: contenuto.label + ' (massima)', unitmeas: contenuto.unitmeas, data: []};
            contenuto.data.forEach(element => {
                let valore = {MINIMO: null, MASSIMO: null};
                if (element.value) {
                    valore = JSON.parse(element.value);
                }
                const giorno = new Date().ConvData( element.date );
                sensors[ key + "_MIN" ].data.push( { date: element.date, value: valore.MINIMO, timestamp: giorno } );
                sensors[ key + "_MAX" ].data.push( { date: element.date, value: valore.MASSIMO, timestamp: giorno } );
            });
        }
        if (key.indexOf('DVENTO') >= 0 ) {   
            sensors[ key + "_GRADI" ] = { label: contenuto.label, unitmeas: contenuto.unitmeas, data: []};
            sensors[ key + "_SETTORE" ] = { label: contenuto.label, unitmeas: 'settore', data: []};
            contenuto.data.forEach(element => {
                let valore = {GRADI: null, SETTORE: null};
                if (element.value) {
                    valore = JSON.parse(element.value);
                }
                const giorno = new Date().ConvData( element.date );
                sensors[ key + "_GRADI" ].data.push( { date: element.date, value: valore.GRADI, timestamp: giorno } );
                sensors[ key + "_SETTORE" ].data.push( { date: element.date, value: valore.SETTORE, timestamp: giorno } );
            });
        }
        if (key.indexOf('VRAFFICA') >= 0 ) {   
            sensors[ key + "_MASSIMO" ] = { label: contenuto.label, unitmeas: contenuto.unitmeas, data: []};
            sensors[ key + "_OREMINUTI" ] = { label: contenuto.label, unitmeas: 'ore:minuti', data: []};
            contenuto.data.forEach(element => {
                let valore = {MASSIMO: null, OREMINUTI: null};
                if (element.value) {
                    valore = JSON.parse(element.value);
                }
                const giorno = new Date().ConvData( element.date );
                sensors[ key + "_MASSIMO" ].data.push( { date: element.date, value: valore.MASSIMO, timestamp: giorno } );
                sensors[ key + "_OREMINUTI" ].data.push( { date: element.date, value: valore.OREMINUTI, timestamp: giorno } );
            });
        }

    });

    return sensors;

}


