// ritorna l'altezza del sensore
function AltezzaSensore(type) {
    var metriVento = type;
    if ( type.indexOf( '2M' ) >= 0 ) { metriVento = 2; }
    if ( type.indexOf( '5M' ) >= 0 ) { metriVento = 5; }
    if ( type.indexOf( '8M' ) >= 0 ) { metriVento = 8; }
    if ( type.indexOf( '10M' ) >= 0 ) { metriVento = 10; }
    return metriVento;
}


