    const t = document.createElement('div');
    t.setAttribute('class', 'modal-body');
//        t.setAttribute('style', 'height: 800px;overflow-y: scroll;');
    t.innerHTML = tabDati +
                    '<a href="' + linkJsonDati + '" target="_blank" type="text/json">Dati della stazione in formato JSON</a>' +
                    '<br><a href="#" id="lnkSalvaTabellaDati">Dati della stazione in formato CSV</a>';

    // metto la tabella nel suo posto
    document.getElementById('agroTabellaDati').append(t);

    // download CSV della tabella visualizzata (separatore ',' per Excel)
    document.getElementById('lnkSalvaTabellaDati').onclick = function (ev) {
        ev.preventDefault();
        const tabella = document.getElementById('tabellaDati');
        if (!tabella) { return; }

        const separatore = ',';
        const escapeCsv = function (valore) {
            const testo = (valore || '').replace(/\s+/g, ' ').trim();
            if (testo.indexOf('"') >= 0 || testo.indexOf(separatore) >= 0 || testo.indexOf('\n') >= 0) {
                return '"' + testo.replaceAll('"', '""') + '"';
            }
            return testo;
        };

        const estraiRigheCsv = function (rows, trimLeadingEmpty) {
            const righeCsv = [];
            const occupateFinoA = [];

            rows.forEach((riga, idxRiga) => {
                const celleCsv = [];
                let idxColonna = 0;

                // salta le colonne coperte da rowspan delle righe precedenti
                while (occupateFinoA[idxColonna] > idxRiga) {
                    celleCsv[idxColonna] = '';
                    idxColonna += 1;
                }

                riga.querySelectorAll('th,td').forEach((cella) => {
                    while (occupateFinoA[idxColonna] > idxRiga) {
                        celleCsv[idxColonna] = '';
                        idxColonna += 1;
                    }

                    const colspan = parseInt(cella.getAttribute('colspan') || '1', 10);
                    const rowspan = parseInt(cella.getAttribute('rowspan') || '1', 10);
                    const valore = escapeCsv(cella.innerText);

                    for (let i = 0; i < colspan; i++) {
                        celleCsv[idxColonna + i] = valore;
                        if (rowspan > 1) {
                            occupateFinoA[idxColonna + i] = idxRiga + rowspan;
                        }
                    }
                    idxColonna += colspan;
                });

                // normalizzo eventuali buchi interni
                for (let i = 0; i < celleCsv.length; i++) {
                    if (celleCsv[i] === undefined) {
                        celleCsv[i] = '';
                    }
                }

                // evito delimitatori a fine riga per celle vuote non significative
                while (celleCsv.length > 0 && celleCsv[celleCsv.length - 1] === '') {
                    celleCsv.pop();
                }

                // nel tbody non voglio delimitatori in testa dovuti a celle vuote spurie
                if (trimLeadingEmpty) {
                    while (celleCsv.length > 0 && celleCsv[0] === '') {
                        celleCsv.shift();
                    }
                }

                righeCsv.push(celleCsv);
            });

            return righeCsv;
        };

        const headerRows = tabella.tHead ? Array.from(tabella.tHead.rows) : [];
        const bodyRows = tabella.tBodies.length > 0 ? Array.from(tabella.tBodies[0].rows) : [];
        const righeCsvFinali = estraiRigheCsv(headerRows, false).concat(estraiRigheCsv(bodyRows, true));

        const righeCsvTesto = righeCsvFinali.map((celleCsv) => celleCsv.join(separatore));
        const csv = '\uFEFF' + righeCsvTesto.join('\r\n');
        const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'tabellaDati_' + nomeStazione.replaceAll(' ', '_') + '.csv';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

    // 18/07/2023 al momento NON faccio link al salvataggio del file in csv
    // createCSV('tabellaDati', 'meteoTabPanelContent');

}

/**
 * createCSV: converte la tabella idTabella in csv per metterla in idContent
 */
function createCSV(idTabella, idContent) {
    myConsoleLog('createCSV ' + idTabella + ' ' + idContent);

    const table = document.getElementById(idTabella);


    var titoliCsv = '';
    var nColonne = 0;
    // titoli delle colonne
    for (var j = 0, col; col = table.rows[0].cells[j]; j++) {
        const inner = col.innerHTML.replaceAll('<br>', ' ');
        let aggiungi = true;
        if ( inner.indexOf("aria") >= 0) {
            aggiungi = false;
            titoliCsv += inner + ' min;' + inner + ' med;' + inner + ' max;';
            nColonne += 3;
        }
        if ( inner.indexOf("Umidit") >= 0) {
            aggiungi = false;
            titoliCsv += inner + ' min;' + inner + ' max;';
            nColonne += 2;
        }
        if ( inner.indexOf("Vento") >= 0) {
            aggiungi = false;
            titoliCsv += inner + ' velocità;' + inner + ' raffica ora;' + inner + ' raffica m/s;' + inner + ' direz;';
            nColonne += 4;
        }
        if ( inner.indexOf("idrometric") >= 0) {
            aggiungi = false;
            titoliCsv += inner + ' min;' + inner + ' med;' + inner + ' max;';
            nColonne += 3;
        }
        if ( inner.indexOf("suolo") >= 0) {
            aggiungi = false;
            titoliCsv += inner + ' a 0cm;' + inner + ' a -10cm;' + inner + ' a -20cm;' + inner + ' a -30cm;';
            nColonne += 4;
        }

        if (aggiungi) {
            titoliCsv += inner + ';';
            nColonne += 1;
        }

    }
    // togliere l'ultimo ; e mettere a \n
    titoliCsv = titoliCsv.substring(0, titoliCsv.length-1) + '\n';

    var righeCsv = '';

    for (var i = 0, row; row = table.rows[i]; i++) {
        //iterate through rows
        //rows would be accessed using the "row" variable assigned in the for loop
        // salto tutte le righe che non hanno il numero di colonne previste
        if (row.cells.length != nColonne ) {
            continue;
        }

        for (var j = 0, col; col = row.cells[j]; j++) {
            //iterate through columns
            //columns would be accessed using the "col" variable assigned in the for loop
            var inner = col.innerHTML.replaceAll('<br>', ' ');
            inner = col.innerHTML.replaceAll('&gt;', '>');
            const separatore = ( ( j == row.cells.length-1 ) ? '\n' : ';');
            righeCsv += inner + separatore;
        }  
    }

    const tutta = titoliCsv + righeCsv;

    // per salvare in formato excel https://stackoverflow.com/questions/19492846/javascript-to-csv-export-encoding-issue
    // You should add the UTF-8 BOM at the start of the text, like:
    var element = document.createElement('a');
    element.setAttribute('href', 'data:text/csv;charset=UTF-8,%EF%BB%BF' + encodeURI(tutta));
    element.setAttribute('download', nomeStazione + '.csv');
    element.innerHTML = 'Dati della stazione in formato CSV';
    document.getElementById(idContent).append(element);

/*
    var pre = document.createElement("pre");
    pre.textContent = tutta;
    document.getElementById(idContent).append(pre);
*/

}

