/***
 * costruzione del grafico sensore
 */
function initializeChart(type, sensors) {

    // se non ho valori da graficare
    if (! sensors[type].data ) { return; }

    // in base al type realizzo il grafico opportuno
    var objGraph = null;

    // con taria 3 serie: minimo, medio, massimo
    if ( type.indexOf('TARIA') >= 0 ) { 
        objGraph = GraficoTARIA(type, sensors); 
    }
    // con umid 2 serie: minimo,  massimo
    if ( type.indexOf('UMID') >= 0 ) { 
        objGraph = GraficoUMID(type, sensors); 
    }

    // con tsuolo le altre tsuolo
    if ( type.indexOf('TSUOLO') >= 0 ) { 
        objGraph = GraficoTSUOLO(type, sensors); 
    }

    // tutti gli altri sensori li faccio standard
    if ( ! objGraph ) {
        const typeGraph = ( (type == 'PREC') ? 'bar' : 'line');
        objGraph = GraficoStandard(type, sensors[ type ], typeGraph);
    }

}

