// grafico normale. Se su dispositivo mobile nessuna label
function GraficoStandard(type, sensore, tipoGrafico) {

    const ctx = document.getElementById('chart-' + type);

    let label2 = sensore.label;     // questa per la label della serie nel grafico
    let label3 = sensore.label;     // questa per il titolo del grafico
    if (type.indexOf('VENTO') >= 0) {
        // inserisco la scritta prima dell'altezza sensore
        label2 = label2.replace(' vento a ', ' e direzione vento a ');
        label3 = label2;
    }
    if (type.indexOf('TSUOLO') >= 0) {
        label3 = 'Temperatura suolo';
    }
    if (type.indexOf('TARIA') >= 0) {
        label3 = 'Temperatura aria';
    }
    if (type.indexOf('UMID') >= 0) {
        label3 = 'Umidità relativa';
    }

    document.getElementById('nome-' + type).innerHTML = label3;

    let xPointStyle = 'circle';
    let xPointRotation = function(ctx) { return 0; };
    let xPointColor = chartsColors[type];

    // cerco il valore massimo in Y
    var maxY = - Infinity;
    var dMinima = Infinity;
    var dMassima = - Infinity;
    sensore.data.forEach((valore, index) => {
        // trovo la massima delle cumulate per impostare l'asse y1
        maxY = Math.max(maxY, valore.value);
        // periodo del grafico
        const giorno = new Date().ConvData( valore.date );
        dMassima = Math.max(dMassima, giorno);
        dMinima = Math.min(dMinima, giorno);
    });

    // sul mySensor aggiungo sensor.data mettendo tutti i valori assenti al dPasso
    const passo = 1000*60*24;     // un giorno in millisecondi
    var mySensor = [];
    var dAtteso = new Date();
    dAtteso.setTime( dMinima );
    sensore.data.forEach((valore, index) => {
        while ( dAtteso < valore.timestamp ) {
            mySensor.push({
                value: null,
                date: dAtteso.Formato('YYYY-MM-DD'),
                timestamp: dAtteso
            });
            dAtteso.setMilliseconds(dAtteso.getMilliseconds() + passo);
        }
        mySensor.push( valore );
        dAtteso.setMilliseconds(dAtteso.getMilliseconds() + passo);
    });
    // resto dei punti attesi
    while ( dAtteso < dMassima ) {
        mySensor.push({
            value: null,
            date: dAtteso.Formato('YYYY-MM-DD'),
            timestamp: dAtteso
        });
        dAtteso.setMilliseconds(dAtteso.getMilliseconds() + passo);
    }

    // in base al valore massimo aumento di una percentuale diversa
    if (maxY < 1) { 
        maxY += maxY * 0.5; 
    } else {
        maxY += maxY * 0.1; 
    }
    // un solo decimale
    maxY = Math.round( maxY * 10 ) / 10;

    const typeAnchor = ( (type == 'PREC') ? 'end' : 'center' );

    /* https://www.chartjs.org/ */
    const myChart = new ARPAVAPI.Chart(
        ctx, {
        type: tipoGrafico,
        responsive: true,
        plugins: [ARPAVAPI.ChartDataLabels],
        data: {
            datasets: [{
                label: label2,
                data: mySensor,
                datalabels: {
                    color: 'rgb(0, 0, 0)',
                    align: 'end', 
                    anchor: typeAnchor,
                    offset : 2, 
                    rotation: -90, 
                    display: true,
                    formatter: function(point, context) {
                                    // label ogni giorno
                                    var xLab = point.value;
                                    return xLab;
                               }
                },
                fill: false,
                borderColor: chartsColors[type],
                backgroundColor: chartsColors[type],
                tension: 0,
                pointStyle: xPointStyle,
                rotation: xPointRotation,
                pointBackgroundColor: xPointColor,
                pointBorderColor: xPointColor,
                radius: RadiusGrafici(),
                borderWidth: WidthGrafici(),
                parsing: {
                    xAxisKey: 'date',
                    yAxisKey: 'value',
                },
            }]
        },
        options: {
            scales: {
                x: {
                    title: {
                        display: true,
                        text: 'Giorno - mese'
                    },
                    ticks: {
                        callback: function (value, index, ticks) {
                            let date = new Date(this.getLabelForValue(value));
                            return formatDate(date);
                      }
                    }
                },
                y: {
                    title: {
                        display: true,
                        text:  sensore.label + (sensore.unitmeas ? ' (' + sensore.unitmeas + ')' : '')
                    },
                    suggestedMax: maxY,
                }
            },
            plugins: {
                datalabels: {
                       display: false
                   },
                tooltip: {
                    callbacks: {
                        title: context_list => {
                            return new Date(context_list[0].label).toLocaleDateString("it-IT", tooltiplableformat);
                        },
                    }
                }
            }
        },
    });   

    return myChart; 

}


/**
 * Generates HTML
 */
function generateHTML() {

    const codseqst = getParameterByName('codseqst');
    const focus =  getParameterByName('focus');

    // elementi della pagina
    if (codseqst.length == 0) {
        // visualizzo la mappe delle stazioni
        CreaDivMappa();
        // parto dal primo pulsante presente
        let primoPulsante = Object.values(pulsanti)[0].targa;
        document.getElementById( 'btn' + primoPulsante ).click();
    } else {

        // imposto il font di default dei grafici il font della tabella
        if (isMobile() ) {
            ARPAVAPI.Chart.defaults.font.size = 7;
            AddStyle(7);
        } else {
            ARPAVAPI.Chart.defaults.font.size = 16;
            AddStyle(15);
        }
        GraficiStazione(codseqst, focus);

    }


}

generateHTML();
